mapper.select:
select t.ACCT_NO,t.ACCT_TYPE
from PTL_CAPACCT_INFO t
where t.PORTFOLIO_ID = #{portfolioId}

    #{item}

select
to_char(CDATE, 'yyyy-MM-dd') as HOLIDATE
from
VAL_VW_MST_HOLIDAY
where
IS_HOLIDAY > 0

    and CDATE >= #{startDate, jdbcType=DATE}


    and CDATE <= #{endDate, jdbcType=DATE}


    and TRADE_CALENDAR_ID = #{dealCalId}

select DISTINCT t.ACCT_NO AS id, SCI.ACCT_NAME AS text
  from PTL_CAPACCT_INFO t, STL_CAPACCT_INFO SCI
 where T.ACCT_NO = SCI.ACCT_NO
   and t.PORTFOLIO_ID = #{portfolioId}

       #{item}
